from itertools import combinations
from fractions import Fraction
from math import gcd

lower=(3,3,3,0,0); upper=(5,5,5,5,5)
def trim(p):
 p=tuple(p)
 while p and p[-1]==0:p=p[:-1]
 return p
def wt(p):return sum(p)
def key(p):return tuple([-x for x in p]+[0]*(5-len(p)))
def inside(p):
 q=p+(0,)*(5-len(p)); return all(lower[i]<=q[i]<=upper[i] for i in range(5))
def parts(n,maxv=5,maxlen=5):
 out=[]
 def rec(rem,last,a):
  if rem==0:out.append(trim(a));return
  if len(a)==maxlen:return
  for x in range(min(last,rem),0,-1):rec(rem-x,x,a+(x,))
 rec(n,maxv,());return out
def horizontal(mu,k):
 mu=mu+(0,)*(5-len(mu)); ans=[]
 for nu in parts(sum(mu)+k):
  q=nu+(0,)*(5-len(nu))
  if all(q[i]>=mu[i] and (i==4 or mu[i]>=q[i+1]) for i in range(5)):ans.append(trim(q))
 return ans
def det(A):
 n=len(A)
 if n==0:return 1
 B=[list(map(int,r)) for r in A];sign=1;prev=1
 for k in range(n-1):
  piv=next((i for i in range(k,n) if B[i][k]),None)
  if piv is None:return 0
  if piv!=k:B[k],B[piv]=B[piv],B[k];sign=-sign
  pivot=B[k][k]
  for i in range(k+1,n):
   for j in range(k+1,n):B[i][j]=(B[i][j]*pivot-B[i][k]*B[k][j])//prev
  prev=pivot
  for i in range(k+1,n):B[i][k]=0
 return sign*B[-1][-1]
def invsolve(A,b):
 n=len(A);M=[[Fraction(x) for x in A[i]]+[Fraction(b[i])] for i in range(n)]
 for k in range(n):
  p=next(i for i in range(k,n) if M[i][k]);M[k],M[p]=M[p],M[k]
  z=M[k][k];M[k]=[x/z for x in M[k]]
  for i in range(n):
   if i!=k:
    z=M[i][k];M[i]=[M[i][j]-z*M[k][j] for j in range(n+1)]
 return [M[i][-1] for i in range(n)]
def smith_diag(A):
 n=len(A);ds=[];old=1
 for k in range(1,n+1):
  g=0
  for I in combinations(range(n),k):
   for J in combinations(range(n),k):g=gcd(g,abs(det([[A[i][j] for j in J] for i in I])))
  ds.append(g//old);old=g
 return ds
GL=sorted([trim((3,3,3)+rho) for rho in [(a,b) for a in range(3,-1,-1) for b in range(a,-1,-1)]],key=key)
GR=sorted([trim(tuple(3+x for x in rho)) for rho in [(a,b,c) for a in range(2,-1,-1) for b in range(a,-1,-1) for c in range(b,-1,-1)]],key=key)
print('BOUNDARY_CARDINALITIES',len(GL),len(GR));print('GL_ALL',[''.join(map(str,p)) for p in GL]);print('GR_ALL',[''.join(map(str,p)) for p in GR]);assert len(GL)==len(GR)==10
Ts=[]
for d in range(9,16):
 C=sorted([p for p in parts(d) if inside(p)],key=key);idx={p:i for i,p in enumerate(C)};n=len(C);rows=[];labels=[]
 for t in range(1,6):
  for mu in parts(d-t):
   if inside(mu):
    r=[0]*n
    for nu in horizontal(mu,t):
     if nu in idx:r[idx[nu]]+=1
    if any(r):rows.append(r);labels.append('h%d*%s'%(t,''.join(map(str,mu))))
 L=[p for p in GL if wt(p)==d];R=[p for p in GR if wt(p)==d];li=[idx[p] for p in L];ri=[idx[p] for p in R];q=len(L)
 def findcomp(base):
  for I in combinations(range(len(rows)),n-q):
   A=[rows[i] for i in I]+[[int(j==c) for j in range(n)] for c in base]
   if abs(det(A))==1:return I,A
  raise RuntimeError('no complement')
 IL,AL=findcomp(li);IR,AR=findcomp(ri);T=[]
 for c in li:
  x=invsolve([[AR[j][i] for j in range(n)] for i in range(n)],[int(i==c) for i in range(n)])
  T.append([int(y) for y in x[n-q:]]);assert all(y.denominator==1 for y in x[n-q:])
 for rr,c in enumerate(li):
  v=[int(i==c) for i in range(n)]
  for cc,rc in enumerate(ri):v[rc]-=T[rr][cc]
  x=invsolve([[AR[j][i] for j in range(n)] for i in range(n)],v)
  assert all(y.denominator==1 for y in x) and all(x[j]==0 for j in range(n-q,n))
 print('DEGREE',d,'COLUMNS',[''.join(map(str,p)) for p in C]);print('GL',[''.join(map(str,p)) for p in L],'GR',[''.join(map(str,p)) for p in R]);print('REL_SHAPE',len(rows),n,'L_COMP',[labels[i] for i in IL],'R_COMP',[labels[i] for i in IR]);print('T',T,'det',det(T),'SNF',smith_diag(T),'U',T,'V=I','UTV',[[sum(T[i][k]*T[k][j] for k in range(q)) for j in range(q)] for i in range(q)])
 Ts.append(T)
N=sum(len(T) for T in Ts);B=[[0]*N for _ in range(N)];o=0
for T in Ts:
 q=len(T)
 for i in range(q):
  for j in range(q):B[o+i][o+j]=T[i][j]
 o+=q
print('GLOBAL_BLOCK_DIAGONAL',B);print('GLOBAL_DET',det(B),'GLOBAL_SNF',smith_diag(B));print('SUCCESS')
